describe('Record Created and Last Modified Dates', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display created and last modified dates on record details page', () => {
    // Intercept the API call to get record details
    cy.intercept('GET', '/api/records/1').as('getRecordDetails');

    // Navigate to a specific record
    cy.get('[data-testid="record-1"]').click();

    // Wait for the API call to complete
    cy.wait('@getRecordDetails');

    // Verify the record details are visible
    cy.get('[data-testid="record-details-container"]').should('be.visible');

    // Verify created date is displayed
    cy.get('[data-testid="created-date"]').should('contain', 'Created');
    cy.get('[data-testid="created-date"]').should('contain', 'January 1, 2023');

    // Verify last modified date is displayed
    cy.get('[data-testid="last-modified-date"]').should('contain', 'Last Modified');
    cy.get('[data-testid="last-modified-date"]').should('contain', 'January 15, 2023');

    // Verify dates are formatted correctly
    cy.get('[data-testid="created-date"]').should('have.css', 'text-decoration', 'underline');
    cy.get('[data-testid="last-modified-date"]').should('have.css', 'text-decoration', 'underline');
  });

  it('should handle record without created or last modified dates', () => {
    // Intercept the API call to get a record without dates
    cy.intercept('GET', '/api/records/2').as('getRecordWithoutDates');

    // Navigate to the record
    cy.get('[data-testid="record-2"]').click();

    // Wait for the API call to complete
    cy.wait('@getRecordWithoutDates');

    // Verify the record details are visible
    cy.get('[data-testid="record-details-container"]').should('be.visible');

    // Verify created date is not displayed
    cy.get('[data-testid="created-date"]').should('not.exist');

    // Verify last modified date is not displayed
    cy.get('[data-testid="last-modified-date"]').should('not.exist');

    // Verify no error message is displayed
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
